const LOCK = 10, DISTANCE = 64, FLICK_DIST = 32, FLICK_SPEED = 0.5;
const reduce = matchMedia('(prefers-reduced-motion: reduce)');
export function swipeToClose(el: HTMLElement, onClose: () => void) {
  el.style.touchAction = 'pan-y';               // the browser keeps vertical panning; horizontal moves come to us
  let x0 = 0, y0 = 0, t0 = 0, dx = 0, axis: 'x' | 'y' | null = null;
  el.addEventListener('pointerdown', (e) => { x0 = e.clientX; y0 = e.clientY; t0 = e.timeStamp; dx = 0; axis = null; });
  el.addEventListener('pointermove', (e) => {
